1	// RULES.md §"One table, two copies": the delivery constants that both tiers must
2	// agree on live in docs/DESIGN.md §10 and are copied into the server's
3	// constants.ts and the client's config.dart — files that cannot share an import
4	// (TypeScript and Dart). This guard compares the copies BY NAME PAIR, so a value
5	// changed on one side and forgotten on the other is a finding rather than a
6	// production bug that only shows up as messages silently not delivered.
7	//
8	// Why not the canon `shared-constants` guard: that one counts occurrences of a
9	// declared literal per file. Here the literals collide as substrings ("150" is
10	// inside "1500"), the paired identifiers differ by language convention
11	// (WHISPER_RADIUS_M / whisperRadiusM), and a value only stays guarded as long as
12	// someone remembers to declare it. Pairing the declarations by name needs no
13	// per-value upkeep and reads the same table docs/DESIGN.md §10 publishes.
14	//
15	// Dependency-free by design (a local pack's checks must load without the shared
16	// mount): it builds plain finding objects instead of importing the engine helper.
17	
18	const SERVER_FILE = 'firebase/functions/src/constants.ts';
19	const CLIENT_FILE = 'app/lib/config.dart';
20	const DESIGN_FILE = 'docs/DESIGN.md';
21	
22	// The cross-tier constants: server name ↔ client name. A server-only constant
23	// (PRESENCE_TTL_MS, SEND_COOLDOWN_MS) or a client-only one (the heartbeat
24	// cadence) has no pair and is deliberately absent — only values BOTH tiers
25	// carry can drift apart.
26	const PAIRS = [
