1	// RULES.md §"Two encoders, one contract": the client's hand-rolled encoder
2	// (app/lib/geo/geohash.dart) and the server's geofire-common must produce
3	// IDENTICAL strings, and the only thing standing behind that claim is a pair of
4	// known-vector suites that carry the SAME vectors deliberately —
5	// app/test/geohash_test.dart and firebase/functions/test/geohash-compat.test.ts.
6	//
7	// The claim is only as good as the overlap. Add a vector to one suite and not
8	// the other and both suites still pass, on both tiers, forever: the new
9	// coordinate is asserted against one encoder and nothing compares it to the
10	// other. Nothing in either toolchain can see it — the files are in different
11	// languages, run by different runners, in different CI jobs.
12	//
13	// This is the "extending one vector list means extending the other" half of the
14	// section, and it is a static signature: two committed tables of literals that
15	// must agree, the same shape as this pack's cross-tier-constants guard. It does
16	// NOT check that the encoders agree — that is runtime behaviour, is what the
17	// suites themselves are for, and stays prose.
18	//
19	// Detection parses rather than greps: it reads only the assertions written at
20	// the shared production precision 9 (the client's default-precision `encode`
21	// calls, the server's explicit `geohashForLocation([lat, lng], 9)` calls), so
22	// the deliberately unpaired vectors — the client's precision 1/5/11/12 cases,
23	// the server's 10-char default-precision cases — are not mistaken for drift.
24	//
25	// Dependency-free by design (a local pack's checks must load without the shared
26	// mount): it builds plain finding objects instead of importing the engine helper.
27	
28	const DART_FILE = 'app/test/geohash_test.dart';
29	const TS_FILE = 'firebase/functions/test/geohash-compat.test.ts';
30	
31	// `expect(encode(57.64911, 10.40744), 'u4pruydqq');` — the two-argument form
32	// only, which is precision 9 by default (DESIGN.md §3). A call carrying an
33	// explicit `precision:` has a third argument and is deliberately not matched.
34	const DART_VECTOR =
35	  /expect\(\s*encode\(\s*(-?[\d.]+)\s*,\s*(-?[\d.]+)\s*\)\s*,\s*'([0-9a-z]+)'\s*\)/g;
36	// `expect(geohashForLocation([57.64911, 10.40744], 9)).toBe('u4pruydqq');` — the
37	// explicit precision-9 form only; the default-precision calls encode 10 chars
38	// and have no client counterpart.
39	const TS_VECTOR =
40	  /expect\(\s*geohashForLocation\(\s*\[\s*(-?[\d.]+)\s*,\s*(-?[\d.]+)\s*\]\s*,\s*9\s*\)\s*\)\s*\.toBe\(\s*'([0-9a-z]+)'\s*\)/g;
41	
42	const rule = {
43	  id: 'shouts-and-whispers/geohash-vector-parity',
44	  severity: 'blocking',
45	  description: 'The two tiers\' known-vector geohash suites carry the same precision-9 vectors',
46	  doc: '.claudinite/local/packs/shouts-and-whispers/RULES.md',
47	  why: 'the paired suites are the only evidence that the client\'s hand-rolled encoder and the server\'s geofire-common agree; a vector asserted on one side alone is a coordinate nobody ever compared, and both suites stay green while the compatibility claim quietly stops covering it',
48	
49	  run(ctx) {
50	    const out = [];
51	    const say = (file, line, what, fix) => out.push({
52	      rule: rule.id, severity: rule.severity, file, line,
53	      what, why: rule.why, fix, doc: rule.doc,
54	    });
55	
56	    const dartText = ctx.read(DART_FILE);
57	    const tsText = ctx.read(TS_FILE);
58	
59	    // Staleness guard, the idiom the pack's other checks already use: a guard
60	    // that quietly stops finding its subject is worse than no guard.
61	    if (dartText === null || tsText === null) {
62	      const missing = dartText === null ? DART_FILE : TS_FILE;
63	      say(missing, null,
64	        `the geohash vector parity guard cannot read ${missing}`,
65	        'restore the suite, or point the guard at its new home (the paths live at the top of the pack\'s geohash-vector-parity.mjs)');
66	      return out;
67	    }
68	
69	    const dart = vectors(dartText, DART_VECTOR);
70	    const ts = vectors(tsText, TS_VECTOR);
71	
72	    if (!dart.size || !ts.size) {
73	      const empty = !dart.size ? DART_FILE : TS_FILE;
74	      say(empty, null,
75	        `no precision-9 known vectors found in ${empty} — the parity guard has nothing to compare`,
76	        'keep the shared vectors as literal precision-9 assertions in both suites (the client\'s default-precision `encode`, the server\'s explicit `geohashForLocation([lat, lng], 9)`), or point the guard at its new home');
77	      return out;
78	    }
79	
80	    for (const [coord, near] of pairwise(dart, ts)) {
81	      const other = near.opposite.get(coord);
82	
83	      if (other === undefined) {
84	        const [have, want] = near.side === 'dart' ? [DART_FILE, TS_FILE] : [TS_FILE, DART_FILE];
85	        say(want, null,
86	          `${have} asserts (${coord}) → '${near.hash}' at precision 9, but ${want} carries no precision-9 vector for that coordinate`,
87	          `add the same coordinate to ${want} — the suites are the compatibility contract, so a vector only one tier asserts proves nothing about the other`);
88	        continue;
89	      }
90	
91	      if (other.hash !== near.hash && near.side === 'dart') {
92	        say(TS_FILE, other.line,
93	          `the suites disagree on (${coord}): ${DART_FILE} expects '${near.hash}', ${TS_FILE} expects '${other.hash}'`,
94	          'the two encoders must produce identical strings, so one of these expectations is wrong — recompute the vector and fix the suite that is stale, never loosen one to match the other');
95	      }
96	    }
97	
98	    return out;
99	  },
100	};
101	
102	// coordinate key → { hash, line }, for every vector asserted at precision 9.
103	function vectors(text, pattern) {
104	  const found = new Map();
105	  pattern.lastIndex = 0;
106	  let m;
107	  while ((m = pattern.exec(text)) !== null) {
108	    // Compare coordinates as numbers, not spelling: 0 and 0.0 are one point.
109	    const key = `${Number(m[1])}, ${Number(m[2])}`;
