1	import { readdirSync, existsSync } from 'node:fs';
2	import { join, dirname, resolve, basename } from 'node:path';
3	import { fileURLToPath, pathToFileURL } from 'node:url';
4	import { validateManifest, normalizeManifest } from './pack-schema.mjs';
5	import { applyPackConventions, bundledSkillDirs, ruleModuleFiles, RULE_DIRS } from './pack-conventions.mjs';
6	import { canonicalPackId, canonicalPackIdAmong } from './renamed-packs.mjs';
7	
8	// This module lives at <canon>/engine/pack_loader/; the packs it scans at <canon>/packs/.
9	const canonRoot = dirname(dirname(dirname(fileURLToPath(import.meta.url))));
10	const packsDir = join(canonRoot, 'packs');
11	
12	// A repo's own packs live at <root>/.claudinite/local/packs/<name>/ — tracked
13	// project content, discovered and run by the same engine as the mounted canon
14	// packs, and sitting at the same uniform depth as the shared mount
15	// (.claudinite/*/packs/). This is the canonical subdir relative to a consumer's
16	// checkout root. The pre-2026-07 layout put them one level up at
17	// .claudinite/local_packs/; discovery scans BOTH roots until the rename has
18	// propagated fleet-wide (Phase 4 drops the legacy scan), so a repo that hasn't
19	// been git-mv'd yet still loads.
20	export const LOCAL_PACKS_SUBDIR = join('.claudinite', 'local', 'packs');
21	export const LEGACY_LOCAL_PACKS_SUBDIR = join('.claudinite', 'local_packs');
22	export const localPacksDir = (root) => join(resolve(root), LOCAL_PACKS_SUBDIR);
23	export const legacyLocalPacksDir = (root) => join(resolve(root), LEGACY_LOCAL_PACKS_SUBDIR);
24	
25	// Where a consumer materializes the vendored canon (vendoring/DESIGN.md): the
26	// corpus mirrored at canon-relative paths under this subdir. Tracked files in
27	// the interim; the planned future is a git submodule mounted at this same path
28	// — which is why nothing consumer-owned (local_packs/ above) lives inside it.
29	export const SHARED_SUBDIR = join('.claudinite', 'shared');
30	
31	// The full pack directory — the generated catalog of every canon pack a repo
32	// can adopt, rendered from the manifests by its drift test and vendored into
33	// every mount regardless of declaration (a consumer holds only its declared
34	// packs, so without this file a member session has no view of what else it
35	// could add). One definition of the path: the vendor-set computation includes
36	// it, the prose injector points sessions at it.
37	export const PACK_DIRECTORY_FILE = 'packs/directory.GENERATED.md';
38	
39	// Load a directory of `<name>/pack.mjs` manifests, isolating each import so one
40	// broken manifest can't sink the rest (a consumer-authored local pack.mjs must
41	// never disable every other pack's prose/checks/skills). Each loaded pack is
42	// stamped with `dir` (its own directory — prose and bundled skills resolve off
43	// this, so a pack's files never have to sit under a single shared root) and
44	// `local` (whether it came from a consumer's local_packs). A pack's skills live
45	// in its own tree — `<pack>/skills/<skill>/` is the one bundled-skill shape,
46	// canon and local alike (#385: a skill rides exactly one pack; there is no
47	// separate skills collection to own or cross-declare). A bundled skill's
48	// checks.mjs is gathered onto `skillChecks` and run by the runner only when the
49	// pack is active.
50	// A pack's declared adoption questions, validated: `questions` (an optional
51	// manifest field any pack may carry) must be an array of { id, prompt, distill? }
52	// with non-empty string ids and prompts, ids unique within the pack. A malformed
53	// entry is reported and skipped — one bad question must not mute the pack's valid
54	// ones (the registry's fail-soft posture). This is generic manifest-shape
55	// validation, so it lives with pack loading (scanPackDir reports the errors as
56	// load faults); the interview machinery imports it to read the valid questions.
57	export function packQuestions(pack) {
58	  const questions = [];
59	  const errors = [];
60	  const src = pack.questions;
61	  if (src === undefined || src === null) return { questions, errors };
62	  if (!Array.isArray(src)) {
63	    errors.push({
64	      what: `the "${pack.id}" pack declares a non-array "questions"`,
65	      fix: 'make questions an array of { id, prompt } entries',
66	    });
67	    return { questions, errors };
68	  }
69	  const seen = new Set();
70	  for (const q of src) {
71	    if (q === null || typeof q !== 'object' || typeof q.id !== 'string' || !q.id
72	      || typeof q.prompt !== 'string' || !q.prompt) {
73	      errors.push({
74	        what: `the "${pack.id}" pack declares a malformed question ${JSON.stringify(q)}`,
75	        fix: 'give each question a non-empty string "id" and "prompt"',
76	      });
77	      continue;
78	    }
79	    if (seen.has(q.id)) {
80	      errors.push({
81	        what: `the "${pack.id}" pack declares question id "${q.id}" twice`,
82	        fix: 'question ids must be unique within the pack — rename one',
83	      });
84	      continue;
85	    }
86	    seen.add(q.id);
87	    questions.push(q);
88	  }
89	  return { questions, errors };
90	}
91	
92	// A directory's declared checks — `<dir>/declared-checks.json`, compiled by the
93	// pattern-check engine. The declaration file gates the import: a tree with no
94	// declarations never reaches for the checks helpers, so the loader keeps working
95	// wherever only the pack machinery is present. A broken declaration is reported
96	// like a broken manifest, never thrown — the neighbouring coded rules still run.
97	const DECLARED_CHECKS_FILE = 'declared-checks.json';
98	async function declaredChecksIn(dir, label, errors) {
99	  if (!existsSync(join(dir, DECLARED_CHECKS_FILE))) return [];
100	  try {
101	    const { loadDeclaredChecks } = await import('../checks/helpers/pattern-rules.mjs');
102	    return loadDeclaredChecks(dir);
103	  } catch (e) {
104	    errors.push({ what: `the declared checks in ${label} failed to load: ${e.message}`, fix: `fix ${DECLARED_CHECKS_FILE} in ${label}`, dir });
105	    return [];
106	  }
107	}
108	
109	// One scope's coded rules, imported in filename order. Isolated per module for
110	// the reason a manifest's own import was not: a manifest that failed to import
111	// took the whole pack with it, where a rule module that does is now one reported
112	// fault beside its working neighbours. A module exporting no rule is the same
113	// class of fault — a file sitting in the directory contributing nothing is what
114	// this reports rather than silently drops.
115	async function ruleModulesIn(packDir, scope, label, errors) {
116	  const rules = [];
117	  for (const file of ruleModuleFiles(packDir, scope)) {
118	    const name = `${scope}/${basename(file)}`;
119	    let rule;
120	    try {
121	      rule = (await import(pathToFileURL(file).href)).default;
122	    } catch (e) {
123	      errors.push({ what: `${label}/${name} failed to load: ${e.message}`, fix: `fix ${name}, or remove it from the pack`, dir: packDir });
124	      continue;
125	    }
126	    if (rule === null || typeof rule !== 'object' || typeof rule.id !== 'string' || typeof rule.run !== 'function') {
127	      errors.push({
128	        what: `${label}/${name} sits in a rule directory but default-exports no rule`,
129	        fix: `default-export { id, severity, description, doc, why, run(ctx) } from ${name}, or move the module out of ${scope}/`,
130	        dir: packDir,
131	      });
132	      continue;
133	    }
134	    rules.push(rule);
135	  }
136	  return rules;
137	}
138	
139	async function scanPackDir(dir, { local, subdir }, errors) {
140	  const out = [];
141	  if (!existsSync(dir)) return out;
142	  const label = subdir ?? (local ? LOCAL_PACKS_SUBDIR : 'packs');
143	  // A non-directory (or unreadable path) at a scan root is a fault to REPORT, not
144	  // a crash — the whole point of discovery being fail-soft is a diagnostic instead
145	  // of a dead runner (the SessionStart hooks fail soft; the runner surfaces it).
146	  let names;
147	  try {
148	    names = readdirSync(dir, { withFileTypes: true })
149	      .filter((d) => d.isDirectory()).map((d) => d.name).sort();
150	  } catch (e) {
151	    errors.push({
152	      what: `${label} is not a readable directory: ${e.message}`,
153	      fix: `make ${label} a directory (or remove it)`,
154	      dir,
155	    });
156	    return out;
157	  }
158	  for (const name of names) {
159	    const packDir = join(dir, name);
160	    const rel = local ? `${label}/${name}` : `packs/${name}`;
161	    const manifest = join(packDir, 'pack.mjs');
162	    if (!existsSync(manifest)) continue;
163	    let mod;
164	    try {
165	      mod = (await import(pathToFileURL(manifest).href)).default;
166	    } catch (e) {
167	      errors.push({
168	        what: `the pack in ${rel} failed to load: ${e.message}`,
169	        fix: `fix pack.mjs in ${rel}, or remove the pack`,
170	        dir: packDir,
171	      });
172	      continue;
173	    }
174	    // The tree's own answers first — id, prose, badge and skills come from the pack
175	    // directory, and the manifest overrides only what it actually declares
176	    // (pack-conventions.mjs). Everything below reads one merged manifest, so no
177	    // reader has to know which half a field came from.
178	    mod = applyPackConventions(mod, packDir, name);
179	    // The convention supplies the id, so reaching here without a string one means
180	    // the export is not an object to merge into at all, or it overrode the id with
181	    // something that is not a name. Either way there is nothing to activate.
182	    if (!mod || typeof mod.id !== 'string') {
183	      errors.push({
184	        what: `the pack in ${rel} has no object default export carrying a usable id`,
185	        fix: 'export default { version, ruleRoutingGuidance, ... } from its pack.mjs — the id is the directory name unless the manifest overrides it with a string',
186	        dir: packDir,
187	      });
188	      continue;
189	    }
190	    // A local pack's id must equal its directory name. The convention gives it that
191	    // for free, so this can only fire on a manifest that OVERRODE the id — and the
192	    // override is exactly what must not be allowed here: the engine activates a pack
193	    // by its exported id, but the fleet planner reads a local pack's daily tasks by
194	    // directory name (it never imports pack.mjs), so a mismatch would silently
195	    // diverge — the engine runs the pack while the fleet skips its task.
196	    if (local && mod.id !== name) {
197	      errors.push({
198	        what: `the local pack in ${rel} exports id "${mod.id}" but its directory is "${name}"`,
199	        fix: `rename the directory to "${mod.id}", or set the pack's id to "${name}" — a local pack's id must match its directory name`,
200	        dir: packDir,
201	      });
202	      continue;
203	    }
204	    // A malformed `questions` manifest field is a load fault like any other —
205	    // reported here so the runner surfaces it pack-agnostically, no interview
206	    // import needed (the pack owns the interview HYGIENE check; the engine owns
207	    // the manifest-shape validation).
208	    for (const e of packQuestions(mod).errors) errors.push({ ...e, dir: packDir });
209	    // The rest of the manifest against the spec (pack-schema.mjs). REPORTED, not
210	    // fatal: a pack whose declaration is incomplete still loads and still runs
211	    // its checks — silently disabling a repo's own rules is a worse failure than
212	    // the one being reported, and the blocking config error is what gets it fixed.
213	    for (const e of validateManifest(mod, { label: `the pack in ${rel}`, skillDirs: bundledSkillDirs(packDir) })) {
214	      errors.push({ ...e, dir: packDir });
215	    }
216	    // The pack's declared checks (declared-checks.json — data, not a module) ride
217	    // its rule lists: discovered structurally like the pack itself, so a
218	    // declaration is added by writing it, with no manifest line to keep in sync.
219	    // A coded rule's scope is the list it sits in; a declaration has no list, so
220	    // its own `scope` picks the list it joins — and normalizeManifest stamps the
221	    // same answer back either way.
222	    const declared = await declaredChecksIn(packDir, rel, errors);
223	    // The pack's CODED rules, discovered the same way its declared ones already
224	    // were: `<pack>/worldRules/*.mjs` and `<pack>/workRules/*.mjs`, each module
225	    // default-exporting one rule. A manifest that declares the list overrides the
226	    // directory, exactly like every other convention — which is why the scan runs
227	    // only for a scope the manifest left unspoken.
228	    const scanned = {};
229	    for (const scope of RULE_DIRS) {
230	      if (mod[scope] !== undefined) continue;
231	      scanned[scope] = await ruleModulesIn(packDir, scope, rel, errors);
232	    }
233	    // A CANON pack's own id is canonicalized like a declared one. A member's mount
234	    // is replaced per pack and per version, so a repo can hold a pack DIRECTORY
235	    // renamed by a migration record while the `pack.mjs` inside it still carries the
236	    // old id — the tree is only rewritten once the canon ships a version above the
237	    // one that repo has. Read literally, that pack announces an id nothing declares
238	    // and goes inert, taking its checks, prose and tasks with it silently. A local
239	    // pack keeps its own id: that namespace is the repo's.
240	    //
241	    // The raw id rides along because that canonicalization is only safe once the
242	    // WHOLE tree is known — an absorbed pack's leftover directory maps onto a
243	    // survivor that is itself present, and discoverPacks below undoes the map for
244	    // exactly that case (#1186).
245	    const pack = { ...normalizeManifest({ ...mod,
246	      ...(local ? {} : { id: canonicalPackId(mod.id), rawId: mod.id }),
247	      worldRules: [...(mod.worldRules ?? scanned.worldRules ?? []), ...declared.filter((r) => r.scope !== 'work')],
248	      workRules: [...(mod.workRules ?? scanned.workRules ?? []), ...declared.filter((r) => r.scope === 'work')],
249	    }), dir: packDir, local };
250	    pack.skillChecks = await scanSkillChecks(packDir, errors);
251	    out.push(pack);
252	  }
253	  return out;
254	}
255	
256	// A pack's skill-owned checks: any <pack>/skills/<skill>/checks.mjs (default
257	// export = an array of coded rules) plus its declared-checks.json (the same
258	// declaration format a pack's own carries). Isolated per skill; run gated by the
259	// owning pack being active, exactly like the pack's own rules — a skill is pack
260	// content, so its checks ride the pack's activation.
261	async function scanSkillChecks(packDir, errors) {
262	  const rules = [];
263	  const skillsRoot = join(packDir, 'skills');
264	  if (!existsSync(skillsRoot)) return rules;
265	  let names;
266	  try {
267	    names = readdirSync(skillsRoot, { withFileTypes: true })
268	      .filter((d) => d.isDirectory()).map((d) => d.name).sort();
269	  } catch (e) {
270	    errors.push({ what: `${LOCAL_PACKS_SUBDIR} skills path is not a readable directory: ${e.message}`, fix: 'make the pack\'s skills/ a directory (or remove it)', dir: skillsRoot });
271	    return rules;
272	  }
273	  for (const name of names) {
274	    const skillDir = join(skillsRoot, name);
275	    rules.push(...await declaredChecksIn(skillDir, `the ${name} skill`, errors));
276	    const manifest = join(skillDir, 'checks.mjs');
277	    if (!existsSync(manifest)) continue;
278	    try {
279	      rules.push(...(await import(pathToFileURL(manifest).href)).default);
280	    } catch (e) {
281	      errors.push({ what: `local skill check ${name}/checks.mjs failed to load: ${e.message}`, fix: 'fix or remove the skill\'s checks.mjs', dir: skillDir });
282	    }
283	  }
284	  return rules;
285	}
286	
287	// Discover every pack structurally — canon `packs/<name>/pack.mjs` always, plus a
288	// consumer's own `<localRoot>/.claudinite/local_packs/<name>/pack.mjs` when a
289	// localRoot is given (the repo under test / the session's project root). No
290	// registry list to maintain — dropping a directory in adds it. Returns the packs
291	// plus any load-time `errors` (a broken manifest, a missing id, an id collision);
292	// the runner surfaces those as blocking `config` findings, the fail-soft
293	// SessionStart hooks just skip the offending pack. Canon is scanned first, so a
294	// local pack may not shadow a canon id — the collision is reported and the local
295	// one dropped (a consumer extends the canon, never silently overrides it).
296	export async function discoverPacks({ localRoot } = {}) {
297	  const errors = [];
298	  const canon = await scanPackDir(packsDir, { local: false }, errors);
299	  // Re-resolve each canon id now the whole tree is known, so an ABSORBED pack's
300	  // leftover directory keeps its own id instead of colliding with the survivor
301	  // sitting beside it (#1186). scanPackDir cannot make this call alone: it sees
302	  // one directory at a time, and the map reads the same for a rename.
303	  const rawCanonIds = new Set(canon.map((p) => p.rawId));
304	  for (const pack of canon) pack.id = canonicalPackIdAmong(pack.rawId, rawCanonIds);
305	  // Scan BOTH local roots (canonical .claudinite/local/packs and the legacy
306	  // .claudinite/local_packs) so a repo mid-rename still loads; a pack present in
307	  // both would trip the id-collision guard below, which is the desired signal.
308	  const local = localRoot
309	    ? [
310	      ...await scanPackDir(localPacksDir(localRoot), { local: true, subdir: LOCAL_PACKS_SUBDIR }, errors),
311	      ...await scanPackDir(legacyLocalPacksDir(localRoot), { local: true, subdir: LEGACY_LOCAL_PACKS_SUBDIR }, errors),
312	    ]
313	    : [];
314	  const byId = new Map();
315	  const packs = [];
316	  for (const pack of [...canon, ...local]) {
317	    if (byId.has(pack.id)) {
318	      const first = byId.get(pack.id);
319	      errors.push({
320	        what: `pack id "${pack.id}" is declared twice — by ${first.local ? 'a local pack' : 'the canon'} and ${pack.local ? 'a local pack' : 'the canon'}`,
321	        fix: `rename the local pack in ${LOCAL_PACKS_SUBDIR}/ — a local pack id must be unique and may not shadow a canon pack`,
322	        dir: pack.dir,
323	      });
324	      continue;
325	    }
326	    byId.set(pack.id, pack);
327	    packs.push(pack);
328	  }
329	  return { packs, errors };
330	}
331	
332	// The pack list alone — the shape every non-runner caller wants. Canon-only when
333	// no localRoot is given (the fleet planner and the declaration-writing backfill
334	// run in the canon checkout and read member declarations over the API, not from
335	// local disk). A broken/duplicate pack is simply absent here; the runner's
336	// discoverPacks surfaces the diagnostic.
337	export async function loadPacks(opts) {
338	  return (await discoverPacks(opts)).packs;
339	}
340	
341	// A local pack's canonical declaration token is namespaced `local/<id>` —
342	// self-documenting in .claudinite-settings.json (a reader sees at a glance the
343	// pack lives in the repo's own tree under .claudinite/local/, and a canon id can
344	// never be claimed by accident; the discoverPacks shadow guard stays as the
345	// backstop). Both the pre-rename `local_packs/<id>` form and the bare id remain
346	// accepted while the fleet migrates (baselining's normalization + the
347	// local-pack-namespace migration track convergence), so packEntryId strips
348	// whichever prefix is present and every id comparison happens on the bare id.
349	export const LOCAL_DECL_PREFIX = 'local/';
350	export const LEGACY_LOCAL_DECL_PREFIX = 'local_packs/';
351	const stripLocalPrefix = (id) => {
352	  for (const prefix of [LOCAL_DECL_PREFIX, LEGACY_LOCAL_DECL_PREFIX]) {
353	    if (id.startsWith(prefix)) return id.slice(prefix.length);
354	  }
355	  return id;
356	};
357	
358	// The writer-side inverse: the token a declaration writer records for a pack —
359	// namespaced (canonical form) for a local pack, the bare id for a canon one.
360	export const declTokenFor = (pack) =>
361	  pack.local ? LOCAL_DECL_PREFIX + pack.id : pack.id;
362	
363	// A `packs` declaration entry is either a plain id string or an entry object
364	// `{ id, config?, rules?, accept?, via? }` carrying that pack's own settings
365	// (see engine/checks/README.md). This is the one id-extractor every reader shares, so
366	// raw-JSON consumers (the SessionStart hooks, the fleet signal probe) and the
367	// engine agree on both shapes — and on both declaration forms: it returns the
368	// BARE pack id, stripping a `local_packs/` namespace where one is declared.
369	// Returns undefined for a malformed entry.
370	// A declaration written before a canon pack was renamed resolves to the pack's
371	// CURRENT id here (renamed-packs.mjs), so activation, config lookup and the vendor
372	// set all agree on one spelling no matter which one the member wrote. A LOCAL pack
373	// is exempt: its namespace belongs to the repo, so `local/core` stays `core`.
374	// A local pack declared BARE cannot be told apart from a canon one at this seam and
375	// is canonicalized with the rest — which is harmless while the shadow guard in
376	// discoverPacks keeps a local id from claiming a canon one.
377	export const packEntryId = (entry) => {
378	  const raw = typeof entry === 'string'
379	    ? entry
380	    : entry !== null && typeof entry === 'object' && typeof entry.id === 'string'
381	      ? entry.id
382	      : undefined;
383	  if (raw === undefined) return undefined;
384	  const bare = stripLocalPrefix(raw);
385	  return bare === raw ? canonicalPackId(bare) : bare;
386	};
387	
388	// No pack is active by default. Activation is exactly the project's declaration
389	// in .claudinite-settings.json (bootstrap's --init seeds the default-on packs).
390	export const isActive = (pack, config) =>
391	  (config.packs ?? []).some((entry) => packEntryId(entry) === pack.id);
392	
393	// The MOUNTED SKILL SET: the union of the given packs' bundled skills, as a
394	// Map(name -> the skill's directory). A bundled skill is `<pack>/skills/<name>/`
395	// carrying a SKILL.md — the one shape, canon and local alike (#385). The packs are
396	// taken in the caller's order and the FIRST occurrence of a name wins, so a caller
397	// passing canon packs before local ones resolves a shared name to canon.
398	//
399	// Read off each pack's own `skills`, which the convention fills from that same
400	// directory listing — so this is the tree's answer for every ordinary pack, and a
401	// manifest that withholds a name is honoured here rather than quietly re-derived.
402	//
403	// One definition, two readers: the SessionStart mount hook (mount-skills.mjs) turns
404	// it into `.claude/skills/` symlinks, and the usage fold asks it which skill names a
405	// typed `/command` could possibly be. The mounts themselves are gitignored session
406	// state, so anything reasoning about "what is mounted here" must ask the registry —
407	// this function — and never the mount directory.
408	export function bundledSkillSources(packs) {
409	  const byName = new Map();
410	  for (const pack of packs) {
411	    for (const name of pack.skills ?? []) {
412	      if (byName.has(name)) continue;
413	      const dir = join(pack.dir, 'skills', name);
414	      if (existsSync(join(dir, 'SKILL.md'))) byName.set(name, dir);
415	    }
416	  }
417	  return byName;
418	}
419	
420	// Import closure. A pack can't be imported without the packs it requires: a
421	// release pack builds on its coding pack, a project-class pack on the framework
422	// pack that implements it. A pack names those in its `requires` list.
423	// Given the entries a project declares (id strings or entry objects), return
424	// that set plus every pack reachable through `requires` (transitively).
425	// Declared entries keep their order; each pack's pulled-in dependencies land
426	// right after it, deterministically. This runs when the declaration is
427	// WRITTEN — bootstrap's `--init` and the baselining backfill — so a pack's
428	// prerequisites are materialized into .claudinite-settings.json, visible and
429	// droppable like every other entry (the same reason a seeded pack is written
430	// explicitly rather than defaulted), never resolved implicitly at run time.
431	//
432	// Provenance: a materialized dependency is written as `{ id, via: [...] }`,
433	// `via` naming the resolved packs that directly require it — the file itself
434	// answers "why is this pack declared". An entry already carrying `via`
435	// self-identifies as materialized, so its `via` is recomputed to stay accurate
436	// as dependents come and go (an empty recomputed `via` marks an orphan the
437	// project can drop); a user-authored entry (no `via`) is kept verbatim.
438	// A declared id is kept verbatim even if unknown (settings validation flags
439	// that); a dependency is only materialized when it names a real pack; an
440	// entry with no usable id (a settings error) is preserved untouched — the
441	// writer must never drop what it can't interpret.
442	export function resolveDeclaredPacks(declared, packs) {
443	  const byId = new Map(packs.map((p) => [p.id, p]));
444	  const declaredIds = new Set(declared.map(packEntryId).filter((id) => id !== undefined));
445	  const entryById = new Map();
446	  for (const entry of declared) {
447	    const id = packEntryId(entry);
448	    if (id !== undefined && !entryById.has(id)) entryById.set(id, entry);
449	  }
450	  const orderedIds = [];
451	  const seen = new Set();
452	  const visit = (id) => {
453	    if (seen.has(id)) return;
454	    if (!declaredIds.has(id) && !byId.has(id)) return; // don't materialize a phantom dep
455	    seen.add(id);
456	    orderedIds.push(id);
457	    for (const dep of byId.get(id)?.requires ?? []) visit(dep);
458	  };
459	  for (const entry of declared) {
460	    const id = packEntryId(entry);
461	    if (id !== undefined) visit(id);
462	  }
463	  const via = (id) => orderedIds.filter((p) => byId.get(p)?.requires?.includes(id)).sort();
464	  const resolved = orderedIds.map((id) => {
465	    const entry = entryById.get(id);
466	    if (entry === undefined) return { id, via: via(id) };
467	    if (typeof entry === 'object' && 'via' in entry) return { ...entry, via: via(id) };
468	    return entry;
469	  });
470	  return [...resolved, ...declared.filter((entry) => packEntryId(entry) === undefined)];
471	}
